using Dsm.Shared.Models;

namespace Dsm.Managers.Services;

public class ServicesCombiner
{
    // For POSTs from providers that send ProviderIds. DSM regenerates its own entries from the
    // merged provider state, so every autogenerated entry that carries a ProviderId is replaced.
    // Hand-written entries and entries written before ProviderIds existed survive, and merged
    // services come first, so they win a (Name, Hostname) or (Url, Hostname) tie with them.
    public List<Service> CombineExistingServicesWithMergedServices(
        List<Service> existingServices,
        List<Service> mergedServices)
    {
        var survivors = existingServices.Where(e => !e.Autogenerated || e.ProviderId is null);
        return DedupeAndSort(mergedServices.Concat(survivors));
    }

    // For POSTs from providers that predate ProviderIds: an incoming service replaces the
    // pre-ProviderId entries it overlaps, by hostname, or by name for entries without one. Entries
    // with a ProviderId are never replaced here; only the dedupe can displace them.
    public List<Service> CombineExistingServicesWithLegacyServices(
        List<Service> existingServices,
        List<Service> newServices)
    {
        var newTitles = newServices
            .Select(s => s.Name)
            .ToHashSet();
        var newHostnames = newServices
            .Select(s => s.Hostname)
            .Where(h => !string.IsNullOrEmpty(h))
            .ToHashSet();

        var survivors = existingServices
            .Where(e =>
            {
                if (!e.Autogenerated) return true;
                if (e.ProviderId is not null) return true;
                var overlaps = !string.IsNullOrEmpty(e.Hostname)
                    ? newHostnames.Contains(e.Hostname)
                    : newTitles.Contains(e.Name);
                return !overlaps;
            });

        return DedupeAndSort(newServices.Concat(survivors));
    }

    private static List<Service> DedupeAndSort(IEnumerable<Service> merged)
    {
        var seenNames = new HashSet<(string, string?)>();
        var seenUrls = new HashSet<(string, string?)>();
        var result = new List<Service>();
        foreach (var s in merged)
        {
            if (!seenNames.Add((s.Name, s.Hostname)))
                continue;
            if (!string.IsNullOrEmpty(s.Url) && !seenUrls.Add((s.Url, s.Hostname)))
                continue;
            result.Add(s);
        }

        return result
            .OrderBy(s => s.Category)
            .ThenBy(s => s.Name)
            .ToList();
    }
}
